const navigationScript = `<script>
const M=${JSON.stringify(navData)};const B=location.pathname.startsWith('/koreaaitech-website/')?'/koreaaitech-website':'';const U=u=>{if(!u.startsWith('/'))return u;let [p,h]=u.split('#');if(p!=='/'&&!p.endsWith('/'))p+='/';return B+p+(h?'#'+h:'')};let g=document.querySelector('#gnb');M.forEach(m=>{let d=document.createElement('div');d.className='item';d.innerHTML='<button class="nav" aria-expanded="false">'+m[0]+'</button><div class="mega"><div class="inside"><aside class="menu-card"><h2>'+m[2]+'</h2><p>'+m[3]+'</p><a href="'+U(m[4])+'" '+(m[4].startsWith('http')?'target="_blank" rel="noopener"':'')+'>바로가기 '+(m[4].startsWith('http')?'↗':'→')+'</a></aside><div class="links">'+m[5].map(x=>'<a class="link" href="'+U(x[2])+'" '+(x[2].startsWith('http')?'target="_blank" rel="noopener"':'')+'><strong>'+x[0]+' →</strong><span>'+x[1]+'</span></a>').join('')+'</div></div></div>';g.appendChild(d)});let I=[...document.querySelectorAll('.item')];I.forEach(x=>x.querySelector('.nav').onclick=e=>{e.stopPropagation();let o=!x.classList.contains('open');I.forEach(y=>{y.classList.remove('open');y.querySelector('.nav').setAttribute('aria-expanded','false')});if(o){x.classList.add('open');x.querySelector('.nav').setAttribute('aria-expanded','true')}});document.querySelectorAll('.mega').forEach(x=>x.onclick=e=>e.stopPropagation());document.onclick=()=>I.forEach(x=>{x.classList.remove('open');x.querySelector('.nav').setAttribute('aria-expanded','false')});let h=document.querySelector('#head'),mb=document.querySelector('#mobile');mb.onclick=e=>{e.stopPropagation();h.classList.toggle('mob');let open=h.classList.contains('mob');mb.textContent=open?'✕':'☰';mb.setAttribute('aria-expanded',String(open))};document.querySelectorAll('[data-open]').forEach(a=>a.onclick=e=>{e.preventDefault();let found=I.find(x=>x.querySelector('.nav').textContent===a.dataset.open);if(found)found.querySelector('.nav').click()});
</script>`;

