function shell(title,style,content,description='한국AI기술협회는 AI 교육, 기술자문, 전문가 네트워크와 산업 협력을 통해 개인과 기업의 AI 성장을 지원합니다.'){return `<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="${description}"><title>${title}</title><style>${globalStyle}${style}</style></head><body>${header()}${content}<footer class="footer"><strong>사단법인 한국AI기술협회</strong>AI 교육과 기술, 전문가와 산업을 연결합니다.<br>대표번호 1644-2018 · 서울특별시 서초구 언남11길 16-15, 5층</footer>${navigationScript}</body></html>`}

const home=shell('한국AI기술협회 GNB 프로토타입',homeStyle,`<main><section class="home-hero"><div><em>KOREA AI TECHNOLOGY ASSOCIATION</em><h1>사람과 산업을 잇는<br>AI 기술 파트너</h1><p>교육, 기술자문, R&amp;D 연계와 전문가 커뮤니티를 통해 개인과 기업의 실질적인 AI 전환을 지원합니다.</p><div class="actions"><a class="btn" href="/business">주요사업 살펴보기</a><a class="btn alt" href="/membership">협회 가입 안내</a></div></div></section><div class="notice"><strong>프로토타입 사용법</strong><span>상단 메뉴를 클릭하고 하위 메뉴를 선택해 보세요.</span></div></main>`);

const about=shell('협회 소개 | 한국AI기술협회',aboutStyle,`<main>
<section class="about-hero"><div class="wrap hero-copy"><span class="eyebrow">ABOUT K-AI TECH</span><h1>AI와 사람, 산업을 연결하는<br>실행 중심의 AI 협회</h1><p>한국AI기술협회는 AI 전문가와 기업, 기관이 함께 성장할 수 있도록 교육·기술·네트워크·사업 기회를 연결합니다.</p><div class="btns"><a class="btn" href="#mission">협회 비전 보기</a><a class="btn alt" href="/membership/apply">협회 회원가입</a></div></div></section>
<section class="section"><div class="wrap intro-grid"><h2 class="intro-label">한국AI기술협회는</h2><div class="intro-copy"><p>AI 분야의 교육 전문가, 현업 전문가, 기업과 기관이 모여 AI 기술의 올바른 활용과 산업 발전을 만들어가는 비영리 협회입니다.</p><p>빠르게 변화하는 AI 환경에서 개인에게는 실무 역량과 성장 기회를, 기업에는 AI 도입과 사업화에 필요한 전문 지원을 제공합니다.</p><p>교육과 세미나에 머무르지 않고 전문가 연결, 프로젝트 협업, 기술자문과 인재 연계까지 이어지는 실질적인 AI 생태계를 구축하고 있습니다.</p></div></div></section>
<section class="section soft" id="mission"><div class="wrap"><div class="section-head"><span class="eyebrow">VISION &amp; MISSION</span><h2>사람과 산업을 잇는 AI 파트너</h2><p>누구나 AI를 이해하고 활용할 수 있는 환경을 만들고, AI 기술이 개인과 기업의 실질적인 성장으로 이어지도록 지원합니다.</p></div><div class="mission-grid"><article class="card"><b>MISSION 01</b><h3>실무 중심 AI 교육</h3><p>일반인과 기업, 공공기관을 대상으로 현장에서 바로 활용할 수 있는 단계별 교육과 컨설팅을 제공합니다.</p></article><article class="card"><b>MISSION 02</b><h3>산업의 AI 전환 지원</h3><p>기업의 문제를 AI 기술과 연결하고, 연구개발과 정부과제 및 사업화로 이어질 수 있도록 지원합니다.</p></article><article class="card"><b>MISSION 03</b><h3>전문가 협력 생태계</h3><p>AI 전문가와 기업, 기관이 지식과 경험을 교류하고 새로운 프로젝트를 함께 만들 수 있도록 지원합니다.</p></article></div></div></section>
<section class="section"><div class="wrap"><div class="section-head"><span class="eyebrow">THREE QUESTIONS</span><h2>한국AI기술협회가 답하는 세 가지 질문</h2><p>기술의 가능성부터 현장 도입과 학습 방향까지, AI 전환에 필요한 답을 함께 찾습니다.</p></div><div class="question-grid"><article class="card"><b>QUESTION 01</b><h3>AI는 어디까지 가능한가?</h3><p>현재 기술로 구현할 수 있는 범위와 한계를 검토하고, 지속적으로 축적해야 할 기술 역량의 방향을 제시합니다.</p></article><article class="card"><b>QUESTION 02</b><h3>AI를 어떻게 도입해야 하는가?</h3><p>산업별 활용 사례를 공유하고, 기업의 업무와 환경에 맞는 AI 전환 전략과 실행 방안을 설계합니다.</p></article><article class="card"><b>QUESTION 03</b><h3>어떤 AI를 배워야 하는가?</h3><p>목적에 맞는 AI 도구와 학습 과정을 안내하고, 분야별 전문가 연결과 실무형 인재 양성을 지원합니다.</p></article></div></div></section>
<section class="section soft"><div class="wrap"><div class="section-head"><span class="eyebrow">OUR VALUE</span><h2>협회가 제공하는 가치</h2><p>배움이 현장의 변화로 이어지도록 교육부터 협업과 사업 기회까지 연결합니다.</p></div><div class="value-grid"><article class="value-card"><span class="num">01</span><div><h3>AI 교육</h3><p>입문부터 실무 전환까지 대상과 목적에 맞는 교육 프로그램을 제공합니다.</p></div></article><article class="value-card"><span class="num">02</span><div><h3>전문가 네트워크</h3><p>개발자, 교육자, 컨설턴트와 산업 전문가가 교류하는 커뮤니티를 운영합니다.</p></div></article><article class="value-card"><span class="num">03</span><div><h3>프로젝트 및 기술자문</h3><p>AI 도입, 모델 선정, 데이터 전략, PoC 설계와 기술 내재화를 지원합니다.</p></div></article><article class="value-card"><span class="num">04</span><div><h3>비즈니스·인재 연결</h3><p>전문가 매칭, 공동 프로젝트, 채용 및 협력 기회를 제공합니다.</p></div></article></div></div></section>
<section class="section" id="events"><div class="wrap"><div class="section-head"><span class="eyebrow">ACTIVITIES</span><h2>AI 기술을 현장과 연결하는 주요 활동</h2><p>다양한 교육과 교류 프로그램을 통해 AI 기술의 활용 경험을 확산합니다.</p></div><div class="activity-grid"><article class="activity"><span>AI EDUCATION</span><h3>일반인·기업·공공기관 대상 실무 교육</h3></article><article class="activity"><span>YOUTH PROGRAM</span><h3>청소년의 창의력을 키우는 AI 교육</h3></article><article class="activity"><span>COMMUNITY</span><h3>전문가 세미나와 회원 네트워킹</h3></article></div><div class="activity-list"><span>AI 실무·콘텐츠 제작 강의</span><span>정기총회 및 회원 교류</span><span>기업 AI 도입·프로젝트 자문</span></div></div></section>
<section class="section soft" id="organization"><div class="wrap greeting"><div class="portrait"><div><b>송진혁 협회장</b><small>한국AI기술협회 · (주)상상력집단 대표</small></div></div><div class="quote"><h2>AI 생태계의 든든한 연결 플랫폼이 되겠습니다</h2><p>AI 기술이 빠르게 발전할수록 기술을 올바르게 이해하고 현장에 적용할 수 있는 역량이 더욱 중요해지고 있습니다.</p><p>한국AI기술협회는 회원이 변화에 능동적으로 대응할 수 있도록 실질적인 교육과 네트워킹, 비즈니스 기회를 제공하겠습니다. 개인의 성장이 기업의 혁신으로, 기업의 혁신이 대한민국 AI 산업의 발전으로 이어질 수 있도록 함께하겠습니다.</p></div></div></section>
<section class="final-cta" id="join"><div class="wrap final-inner"><div><h2>AI의 가능성을 함께 현실로 만들어갑니다</h2><p>AI를 배우고 활용하려는 개인부터 AI 전환을 준비하는 기업과 기관까지 함께합니다.</p></div><div class="btns"><a class="btn" href="/membership/apply">협회 회원가입</a><a class="btn alt" href="#contact">교육·협력 문의</a></div></div></section>
</main>`);

const organization=shell('조직 안내 | 한국AI기술협회',organizationStyle,`<main>
<section class="org-hero"><div class="wrap"><span class="eyebrow">ORGANIZATION</span><h1>전문성과 실행력을<br>연결하는 조직</h1><p>한국AI기술협회는 AI 전문가와 기업, 기관이 전문 지식과 현장 경험을 공유하고 함께 성장할 수 있도록 체계적인 협력 조직을 운영합니다.</p><div class="btns"><a class="btn" href="#organization-chart">조직도 보기</a><a class="btn alt" href="#participate">전문위원 참여</a></div></div></section>
<section class="section"><div class="wrap"><div class="section-head"><span class="eyebrow">OPERATING PRINCIPLES</span><h2>전문성·투명성·협력을 바탕으로 운영합니다</h2><p>명확한 역할과 책임을 바탕으로 회원과 산업 현장에 실질적인 가치를 제공합니다.</p></div><div class="principles"><article class="principle"><b>01</b><h3>전문성</h3><p>AI 교육과 기술개발, 산업 적용 경험을 보유한 전문가를 중심으로 사업을 운영합니다.</p></article><article class="principle"><b>02</b><h3>투명성</h3><p>명확한 의사결정 체계와 책임 있는 운영을 통해 신뢰받는 협회를 만들어갑니다.</p></article><article class="principle"><b>03</b><h3>협력</h3><p>회원과 전문가, 기업 및 공공기관이 공동 프로젝트와 지식 교류에 참여할 수 있는 환경을 제공합니다.</p></article></div></div></section>
<section class="section soft" id="organization-chart"><div class="wrap"><div class="section-head"><span class="eyebrow">ORGANIZATION CHART</span><h2>전문 분야와 주요사업을 연결하는 협력 구조</h2><p>의사결정 조직과 실행 조직, 분야별 전문위원회가 유기적으로 협력합니다.</p></div><div class="org-chart"><div class="org-node">회원 총회</div><div class="org-line"></div><div class="org-node">이사회</div><div class="org-line"></div><div class="org-node blue">협회장</div><div class="org-line"></div><div class="org-row"><div class="org-branch"><div class="org-node">사무국</div></div><div class="org-branch"><div class="org-node">전문위원회</div><div class="committee-row"><div class="org-node">AI 교육·인재</div><div class="org-node">기술·R&amp;D</div><div class="org-node">산업협력·자문</div><div class="org-node">세미나·커뮤니티</div></div></div></div><p class="chart-note">※ 세부 조직과 위원회 명칭은 협회 정관 및 확정 명단에 따라 조정됩니다.</p></div></div></section>
<section class="section"><div class="wrap leader"><div class="leader-card"><div><b>송진혁 협회장</b><span>한국AI기술협회 · ㈜상상력집단 대표</span></div></div><div class="leader-copy"><span class="eyebrow">LEADERSHIP</span><h2>협회를 이끄는 사람들</h2><p>AI 교육과 개발, 컨설팅 경험을 바탕으로 협회의 주요사업과 전문가 협력 생태계 구축을 이끌고 있습니다.</p><div class="role-tags"><span>AI 교육</span><span>AI 개발</span><span>컨설팅</span></div><div class="data-note">임원진 정보는 직책·이름·소속·전문 분야·담당 역할 기준으로 구성하며, 협회 확정 명단 수령 후 추가됩니다.</div></div></div></section>
<section class="section soft"><div class="wrap"><div class="section-head"><span class="eyebrow">COMMITTEES</span><h2>전문성을 사업 실행으로 연결합니다</h2><p>협회의 네 가지 주요사업을 중심으로 분야별 전문가가 교육과 기술, 산업 협력을 지원합니다.</p></div><div class="committee-grid"><article class="committee-card"><b>COMMITTEE 01</b><h3>AI 교육·인재위원회</h3><p>대상별 AI 교육과정을 개발하고 현장에 필요한 실무형 AI 인재 양성을 지원합니다.</p></article><article class="committee-card"><b>COMMITTEE 02</b><h3>기술·R&amp;D위원회</h3><p>AI 기술 검토와 연구개발 방향 설정, 정부과제 발굴 및 기술 검증을 지원합니다.</p></article><article class="committee-card"><b>COMMITTEE 03</b><h3>산업협력·자문위원회</h3><p>기업의 AI 도입과 데이터 전략, 모델 선정, PoC 설계 및 산업별 협력사업을 지원합니다.</p></article><article class="committee-card"><b>COMMITTEE 04</b><h3>세미나·커뮤니티위원회</h3><p>AI 세미나와 웨비나, 전문가 교류 프로그램 및 회원 커뮤니티를 기획·운영합니다.</p></article></div></div></section>
<section class="section"><div class="wrap"><div class="section-head"><span class="eyebrow">SECRETARIAT</span><h2>협회의 사업과 회원 활동을 지원합니다</h2><p>사무국은 회원과 전문가, 기업 및 기관의 협력 활동이 원활하게 이어지도록 지원합니다.</p></div><div class="office-grid"><article class="office-card"><h3>회원 운영</h3><ul><li>회원가입 및 회원정보 관리</li><li>전문위원과 강사 연결</li><li>회원 문의 지원</li></ul></article><article class="office-card"><h3>사업 운영</h3><ul><li>교육·세미나 운영</li><li>협회 행사 기획</li><li>사업 및 교육 문의</li></ul></article><article class="office-card"><h3>대외협력</h3><ul><li>기업·기관 파트너십</li><li>협회 소식과 콘텐츠</li><li>산업 협력사업 지원</li></ul></article></div></div></section>
<section class="org-cta" id="participate"><div class="wrap inner"><div><h2>AI 전문성과 경험을 협회와 나누어주세요</h2><p>전문위원 활동과 기업·기관 협력을 통해 대한민국 AI 생태계의 성장을 함께 만들어갑니다.</p></div><div class="btns"><a class="btn" href="#expert-apply">전문위원 신청</a><a class="btn alt" href="#contact">기업·기관 협력 문의</a></div></div></section>
</main>`,'한국AI기술협회의 운영 체계와 협회장, 전문위원회 및 사무국의 주요 역할을 안내합니다.');

